import { useState, useEffect } from "react";

type AppState = "empty" | "loading" | "researching" | "complete" | "error";

interface Step {
  id: number;
  status: "complete" | "warning" | "active" | "pending";
  title: string;
  description: string;
  meta?: string;
  timestamp?: string;
}

interface Source {
  id: number;
  title: string;
  type: string;
  page: string;
  excerpt: string;
  relevance: "High" | "Medium" | "Low";
  evidenceType: string;
}

const EXAMPLE_QUESTIONS = [
  "Who was responsible for the fall of Valen?",
  "What happened after the siege of Aldenmoor?",
  "Which factions were affected by the Northern Accord?",
];

const SOURCES: Source[] = [
  { id: 1, title: "Northern Chronicles", type: "Novel", page: "142", excerpt: "The fall of Valen changed the balance of power across the northern territories, leaving a vacuum that three rival factions raced to fill.", relevance: "High", evidenceType: "Primary Source" },
  { id: 2, title: "The Aldenmoor Wiki", type: "Wiki Article", page: "—", excerpt: "Commander Rael's campaign systematically dismantled Valen's northern alliance through strategic betrayals and siege warfare.", relevance: "High", evidenceType: "Secondary Source" },
  { id: 3, title: "The Iron Codex", type: "Codex", page: "89", excerpt: "Following the city's destruction, seven surrounding regions entered a period of political instability lasting more than two decades.", relevance: "High", evidenceType: "Primary Source" },
  { id: 4, title: "Correspondence of Lord Maevan", type: "Letter", page: "—", excerpt: "I write to warn you: without Valen's garrison the eastern passes are undefended. The consequences will be felt for a generation.", relevance: "Medium", evidenceType: "Primary Source" },
  { id: 5, title: "Council Proceedings — Year 412", type: "Transcript", page: "27", excerpt: "The council voted unanimously to assign blame to Commander Rael's faction, citing evidence of deliberate provocation and resource hoarding.", relevance: "High", evidenceType: "Official Record" },
  { id: 6, title: "Valen: A Military History", type: "Codex", page: "201", excerpt: "Scholars now agree that the siege lasted 43 days, far longer than initially reported, and that supply lines were sabotaged from within.", relevance: "Medium", evidenceType: "Secondary Source" },
];

const COMPLETE_STEPS: Step[] = [
  { id: 1, status: "complete", title: "Initial Retrieval", description: "Searching the archive for information about the fall of Valen.", meta: "5 relevant sources found", timestamp: "0.8s" },
  { id: 2, status: "complete", title: "Evidence Analysis", description: "Relevant evidence found, but information about the aftermath is incomplete.", meta: "Partial match", timestamp: "1.4s" },
  { id: 3, status: "warning", title: "Missing Information", description: "Additional evidence is needed about the consequences of the event.", meta: "Gap identified", timestamp: "1.6s" },
  { id: 4, status: "complete", title: "Follow-up Retrieval", description: 'Running targeted search: "aftermath of the fall of Valen"', meta: "3 additional sources found", timestamp: "2.3s" },
  { id: 5, status: "complete", title: "Evidence Analysis", description: "Additional supporting evidence retrieved and cross-referenced.", meta: "Strong corroboration", timestamp: "2.9s" },
  { id: 6, status: "complete", title: "Sufficiency Check", description: "Enough evidence is available to answer the question with high confidence.", meta: "Evidence is sufficient", timestamp: "3.1s" },
];

const LOADING_STEPS = [
  { label: "Understanding question", done: true },
  { label: "Initial retrieval", done: true },
  { label: "Evaluating evidence", done: false, active: true },
  { label: "Generating follow-up search", done: false, active: false },
  { label: "Final answer", done: false, active: false },
];

// ── Logo ──────────────────────────────────────────────────────────────────────
function Logo() {
  return (
    <div className="flex items-center gap-2.5">
      <div className="w-8 h-8 rounded-xl flex items-center justify-center" style={{ background: "linear-gradient(135deg, #5b5bd6 0%, #818cf8 100%)" }}>
        <svg viewBox="0 0 24 24" fill="none" className="w-4.5 h-4.5">
          <path d="M12 4L18 8V12L12 16L6 12V8L12 4Z" stroke="white" strokeWidth="1.5" strokeLinejoin="round" />
          <path d="M12 9L15 11V13L12 15L9 13V11L12 9Z" fill="white" fillOpacity="0.5" />
        </svg>
      </div>
      <div>
        <div className="text-sm font-semibold text-foreground" style={{ letterSpacing: "-0.02em" }}>AlchemAI</div>
        <div className="text-[9px] text-muted-foreground font-medium tracking-widest uppercase">by AlchemyX</div>
      </div>
    </div>
  );
}

// ── Sidebar ───────────────────────────────────────────────────────────────────
function Sidebar({ appState, onNewResearch }: { appState: AppState; onNewResearch: () => void }) {
  const navItems = [
    { label: "Home", icon: <HomeIcon />, active: true },
    { label: "Explore", icon: <ExploreIcon /> },
    { label: "Library", icon: <LibraryIcon /> },
    { label: "History", icon: <HistoryIcon /> },
  ];

  const historyGroups = [
    {
      label: "Tomorrow",
      items: ["What's something you've learn...", "If you could teleport anywhere...", "What's one goal you want to ac..."],
    },
    {
      label: "7 Days Ago",
      items: ["Ask me anything weird or rand...", "How are you feeling today, real...", "What's one habit you wish you..."],
    },
  ];

  return (
    <aside className="w-56 shrink-0 flex flex-col bg-card border-r border-border h-full">
      <div className="px-4 pt-5 pb-4">
        <Logo />
      </div>

      <div className="px-3 mb-3">
        <div className="flex items-center gap-2 px-3 py-2 rounded-xl bg-muted border border-border">
          <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5 text-muted-foreground shrink-0">
            <circle cx="7" cy="7" r="4" stroke="currentColor" strokeWidth="1.5" />
            <path d="M10 10l2 2" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
          <input placeholder="Search" className="flex-1 bg-transparent text-xs text-foreground placeholder-muted-foreground outline-none" />
          <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5 text-muted-foreground">
            <path d="M3 5h10M5 8h6M7 11h2" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
        </div>
      </div>

      <nav className="px-3 space-y-0.5 mb-4">
        {navItems.map(({ label, icon, active }) => (
          <button
            key={label}
            className={`flex items-center gap-2.5 px-3 py-2 rounded-xl w-full text-left text-sm transition-all ${
              active
                ? "bg-muted text-foreground font-medium"
                : "text-muted-foreground hover:text-foreground hover:bg-muted/60"
            }`}
          >
            <span className={active ? "text-foreground" : ""}>{icon}</span>
            {label}
          </button>
        ))}
      </nav>

      <div className="flex-1 overflow-y-auto px-3 space-y-4">
        {historyGroups.map(({ label, items }) => (
          <div key={label}>
            <div className="text-[10px] font-semibold text-muted-foreground px-3 mb-1.5 uppercase tracking-widest">{label}</div>
            {items.map((item) => (
              <button key={item} className="block w-full text-left px-3 py-1.5 text-xs text-muted-foreground hover:text-foreground hover:bg-muted/60 rounded-lg transition-all truncate">
                {item}
              </button>
            ))}
          </div>
        ))}

        {appState !== "empty" && (
          <div>
            <div className="text-[10px] font-semibold text-muted-foreground px-3 mb-1.5 uppercase tracking-widest">Current</div>
            <button className="block w-full text-left px-3 py-1.5 text-xs text-accent font-medium bg-accent/8 rounded-lg truncate">
              Who was responsible for the fall of Valen...
            </button>
          </div>
        )}
      </div>

      <div className="px-3 py-4 border-t border-border">
        <button className="flex items-center gap-2.5 w-full px-3 py-2 rounded-xl hover:bg-muted transition-all">
          <div className="w-7 h-7 rounded-full flex items-center justify-center text-xs font-semibold text-white shrink-0" style={{ background: "linear-gradient(135deg, #5b5bd6, #818cf8)" }}>
            J
          </div>
          <div className="text-left min-w-0">
            <div className="text-xs font-medium text-foreground truncate">Judha Mayguntya</div>
            <div className="text-[10px] text-muted-foreground truncate">judha.design@gmail.com</div>
          </div>
          <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5 text-muted-foreground ml-auto shrink-0">
            <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>
      </div>
    </aside>
  );
}

// ── Topbar ────────────────────────────────────────────────────────────────────
function Topbar({ onNewResearch }: { onNewResearch: () => void }) {
  return (
    <div className="flex items-center justify-between px-6 py-3 border-b border-border bg-card shrink-0">
      <button className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-muted hover:bg-border text-sm font-medium text-foreground transition-all">
        <div className="w-4 h-4 rounded flex items-center justify-center" style={{ background: "linear-gradient(135deg, #5b5bd6, #818cf8)" }}>
          <svg viewBox="0 0 10 10" fill="none" className="w-2.5 h-2.5"><path d="M5 2L7 3.5V5L5 6.5L3 5V3.5L5 2Z" stroke="white" strokeWidth="1" strokeLinejoin="round" /></svg>
        </div>
        AlchemAI 2.0
        <svg viewBox="0 0 12 12" fill="none" className="w-3 h-3 text-muted-foreground">
          <path d="M3 5l3 3 3-3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>

      <div className="flex items-center gap-2">
        <button
          onClick={onNewResearch}
          className="flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl text-sm font-medium text-white transition-all shadow-sm"
          style={{ background: "linear-gradient(135deg, #5b5bd6 0%, #6d6de0 100%)" }}
        >
          <svg viewBox="0 0 14 14" fill="none" className="w-3.5 h-3.5"><path d="M7 3v8M3 7h8" stroke="white" strokeWidth="2" strokeLinecap="round" /></svg>
          New Chat
        </button>
        <div className="w-7 h-7 rounded-full flex items-center justify-center text-xs font-semibold text-white shrink-0" style={{ background: "linear-gradient(135deg, #5b5bd6, #818cf8)" }}>
          J
        </div>
      </div>
    </div>
  );
}

// ── Gradient orb ──────────────────────────────────────────────────────────────
function GradientOrb() {
  return (
    <div className="relative w-20 h-20 mx-auto mb-8">
      <div
        className="absolute inset-0 rounded-full blur-xl opacity-60"
        style={{ background: "radial-gradient(circle at 40% 35%, #a5b4fc 0%, #818cf8 40%, #6d6de0 70%, #c4b5fd 100%)" }}
      />
      <div
        className="absolute inset-2 rounded-full"
        style={{ background: "radial-gradient(circle at 35% 30%, #c7d2fe 0%, #818cf8 45%, #5b5bd6 100%)", boxShadow: "0 8px 32px rgba(91,91,214,0.35)" }}
      />
    </div>
  );
}

// ── Action chips ──────────────────────────────────────────────────────────────
function ActionChip({ icon, label, active }: { icon: React.ReactNode; label: string; active?: boolean }) {
  return (
    <button
      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
        active
          ? "bg-accent/10 text-accent border border-accent/20"
          : "text-muted-foreground hover:text-foreground hover:bg-muted border border-transparent"
      }`}
    >
      {icon}
      {label}
    </button>
  );
}

// ── Empty state ───────────────────────────────────────────────────────────────
function EmptyState({ onSubmit }: { onSubmit: (q: string) => void }) {
  const [query, setQuery] = useState("");

  return (
    <div className="flex-1 flex flex-col items-center justify-center px-8 pb-12">
      <div className="w-full max-w-2xl animate-fade-in-up">
        <GradientOrb />

        <div className="text-center mb-8">
          <h1 className="text-3xl font-semibold text-foreground mb-1" style={{ letterSpacing: "-0.03em" }}>
            Good Morning, Researcher
          </h1>
          <h2 className="text-3xl font-semibold" style={{ letterSpacing: "-0.03em" }}>
            How Can I{" "}
            <span style={{ background: "linear-gradient(90deg, #5b5bd6, #818cf8)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>
              Assist You Today?
            </span>
          </h2>
        </div>

        <div className="rounded-2xl bg-card border border-border shadow-sm overflow-hidden">
          <textarea
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && query.trim()) onSubmit(query.trim()); }}
            placeholder="Initiate a query or send a command to the AI..."
            rows={3}
            className="w-full bg-transparent text-sm text-foreground placeholder-muted-foreground px-5 pt-5 pb-3 resize-none outline-none leading-relaxed"
          />
          <div className="flex items-center justify-between px-4 py-3 border-t border-border">
            <div className="flex items-center gap-1">
              <ActionChip icon={<AttachIcon />} label="" />
              <ActionChip icon={<ReasoningIcon />} label="Reasoning" />
              <ActionChip icon={<ImageIcon />} label="Create Image" />
              <ActionChip icon={<DeepResearchIcon />} label="Deep Research" active />
            </div>
            <button
              onClick={() => query.trim() && onSubmit(query.trim())}
              disabled={!query.trim()}
              className="w-8 h-8 rounded-xl flex items-center justify-center text-white disabled:opacity-30 transition-all"
              style={{ background: "linear-gradient(135deg, #5b5bd6, #818cf8)" }}
            >
              <svg viewBox="0 0 14 14" fill="none" className="w-3.5 h-3.5">
                <path d="M2 7h10M9 4l3 3-3 3" stroke="white" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </button>
          </div>
        </div>

        <div className="mt-4 flex flex-wrap gap-2 justify-center">
          {EXAMPLE_QUESTIONS.map((q) => (
            <button
              key={q}
              onClick={() => onSubmit(q)}
              className="px-3.5 py-2 rounded-xl bg-card border border-border text-xs text-muted-foreground hover:text-foreground hover:border-accent/30 hover:shadow-sm transition-all"
            >
              {q}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

// ── Loading state ─────────────────────────────────────────────────────────────
function LoadingState({ question }: { question: string }) {
  return (
    <div className="flex-1 flex flex-col items-center justify-center px-8 pb-12">
      <div className="w-full max-w-xl animate-fade-in-up">
        <GradientOrb />

        <div className="mb-6 p-4 rounded-2xl border border-border bg-card shadow-sm">
          <div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-1.5">Your Question</div>
          <p className="text-sm text-foreground leading-relaxed">{question}</p>
        </div>

        <div className="flex items-center gap-3 mb-6">
          <div className="w-6 h-6 rounded-full border-2 border-accent/30 border-t-accent animate-spin-slow" />
          <span className="text-sm font-medium text-foreground">Agent is researching...</span>
        </div>

        <div className="space-y-2.5">
          {LOADING_STEPS.map((step, i) => (
            <div key={step.label} className="flex items-center gap-3 animate-step-enter" style={{ animationDelay: `${i * 0.1}s` }}>
              {step.done ? (
                <div className="w-5 h-5 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(22,163,74,0.15)", border: "1px solid rgba(22,163,74,0.3)" }}>
                  <svg viewBox="0 0 10 10" fill="none" className="w-3 h-3"><path d="M2 5l2.5 2.5L8 3" stroke="#16a34a" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
                </div>
              ) : step.active ? (
                <div className="w-5 h-5 rounded-full flex items-center justify-center shrink-0 animate-pulse-ring" style={{ background: "rgba(91,91,214,0.15)", border: "1.5px solid rgba(91,91,214,0.5)" }}>
                  <div className="w-1.5 h-1.5 rounded-full bg-accent" />
                </div>
              ) : (
                <div className="w-5 h-5 rounded-full border border-border flex items-center justify-center shrink-0">
                  <div className="w-1.5 h-1.5 rounded-full bg-muted-foreground/30" />
                </div>
              )}
              <span className={`text-sm ${step.done ? "text-foreground/60" : step.active ? "text-foreground font-medium" : "text-muted-foreground"}`}>
                {step.label}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// ── Step icon ─────────────────────────────────────────────────────────────────
function StepIcon({ status }: { status: Step["status"] }) {
  if (status === "complete") return (
    <div className="w-6 h-6 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(22,163,74,0.12)", border: "1px solid rgba(22,163,74,0.3)" }}>
      <svg viewBox="0 0 10 10" fill="none" className="w-3 h-3"><path d="M2 5l2.5 2.5L8 3" stroke="#16a34a" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
    </div>
  );
  if (status === "warning") return (
    <div className="w-6 h-6 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(217,119,6,0.12)", border: "1px solid rgba(217,119,6,0.3)" }}>
      <svg viewBox="0 0 10 10" fill="none" className="w-3 h-3"><path d="M5 3v3M5 8v.3" stroke="#d97706" strokeWidth="1.5" strokeLinecap="round" /></svg>
    </div>
  );
  if (status === "active") return (
    <div className="w-6 h-6 rounded-full flex items-center justify-center shrink-0 animate-pulse-ring" style={{ background: "rgba(91,91,214,0.15)", border: "1.5px solid rgba(91,91,214,0.5)" }}>
      <div className="w-1.5 h-1.5 rounded-full bg-accent" />
    </div>
  );
  return <div className="w-6 h-6 rounded-full border border-border flex items-center justify-center shrink-0"><div className="w-1.5 h-1.5 rounded-full bg-muted-foreground/30" /></div>;
}

// ── Timeline ──────────────────────────────────────────────────────────────────
function Timeline({ steps }: { steps: Step[] }) {
  return (
    <div className="relative">
      <div className="absolute left-[11px] top-6 bottom-0 w-px bg-border" />
      <div className="space-y-2">
        {steps.map((step, i) => (
          <div key={step.id} className="relative flex gap-3.5 animate-step-enter" style={{ animationDelay: `${i * 0.08}s` }}>
            <StepIcon status={step.status} />
            <div className={`flex-1 pb-3.5 ${i < steps.length - 1 ? "border-b border-border/50" : ""}`}>
              <div className="flex items-center justify-between gap-2 mb-0.5">
                <div className="flex items-center gap-1.5">
                  <span className="text-[9px] font-mono text-muted-foreground">Step {step.id}</span>
                  <span className={`text-xs font-semibold ${step.status === "warning" ? "text-amber-600" : step.status === "active" ? "text-accent" : "text-foreground"}`}>
                    {step.title}
                  </span>
                </div>
                {step.timestamp && <span className="text-[9px] font-mono text-muted-foreground">{step.timestamp}</span>}
              </div>
              <p className="text-xs text-muted-foreground leading-relaxed mb-1.5">{step.description}</p>
              {step.meta && (
                <span className={`inline-flex items-center text-[9px] font-semibold px-2 py-0.5 rounded-md ${
                  step.status === "complete" ? "bg-green-50 text-green-700 border border-green-200"
                  : step.status === "warning" ? "bg-amber-50 text-amber-700 border border-amber-200"
                  : "bg-accent/8 text-accent border border-accent/20"
                }`}>
                  {step.meta}
                </span>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Metric card ───────────────────────────────────────────────────────────────
function MetricCard({ label, value, accent }: { label: string; value: string; accent?: "green" | "accent" }) {
  return (
    <div className="flex-1 rounded-xl border border-border bg-card p-3 shadow-sm">
      <div className="text-[9px] font-semibold uppercase tracking-widest text-muted-foreground mb-1">{label}</div>
      <div className={`text-base font-semibold ${accent === "green" ? "text-green-600" : accent === "accent" ? "text-accent" : "text-foreground"}`}>{value}</div>
    </div>
  );
}

// ── Citation badge ────────────────────────────────────────────────────────────
function CitationBadge({ n }: { n: number }) {
  return (
    <span className="inline-flex items-center justify-center w-4 h-4 rounded text-[9px] font-bold cursor-pointer align-middle mx-0.5 transition-colors" style={{ background: "rgba(91,91,214,0.12)", color: "#5b5bd6", border: "1px solid rgba(91,91,214,0.25)" }}>
      {n}
    </span>
  );
}

// ── Researching state ─────────────────────────────────────────────────────────
function ResearchingState({ question }: { question: string }) {
  return (
    <div className="flex-1 overflow-y-auto">
      <div className="max-w-2xl mx-auto px-8 py-8">
        <div className="animate-fade-in-up">
          <div className="text-[10px] font-semibold uppercase tracking-widest text-accent mb-1">Agent Research</div>
          <h2 className="text-xl font-semibold text-foreground mb-5" style={{ letterSpacing: "-0.02em" }}>Research in progress</h2>

          <div className="mb-4 p-4 rounded-2xl border border-border bg-card shadow-sm">
            <div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-1.5">Question</div>
            <p className="text-sm text-foreground leading-relaxed">{question}</p>
          </div>

          <div className="flex gap-2 mb-6">
            <MetricCard label="Iterations" value="3" accent="accent" />
            <MetricCard label="Sources Retrieved" value="8" accent="accent" />
            <MetricCard label="Evidence" value="Sufficient" accent="green" />
            <MetricCard label="Status" value="Complete" accent="green" />
          </div>

          <h3 className="text-sm font-semibold text-foreground mb-4">Retrieval Timeline</h3>
          <Timeline steps={COMPLETE_STEPS} />
        </div>
      </div>
    </div>
  );
}

// ── Complete state ────────────────────────────────────────────────────────────
function CompleteState({ question }: { question: string }) {
  return (
    <div className="flex-1 overflow-y-auto">
      <div className="max-w-2xl mx-auto px-8 py-8 space-y-5">
        <div className="animate-fade-in-up">
          <div className="text-[10px] font-semibold uppercase tracking-widest text-accent mb-1">Agent Research</div>
          <h2 className="text-xl font-semibold text-foreground mb-5" style={{ letterSpacing: "-0.02em" }}>Research complete</h2>

          <div className="p-4 rounded-2xl border border-border bg-card shadow-sm mb-4">
            <div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-1.5">Question</div>
            <p className="text-sm text-foreground leading-relaxed">{question}</p>
          </div>

          <div className="flex gap-2 mb-5">
            <MetricCard label="Iterations" value="3" accent="accent" />
            <MetricCard label="Sources Retrieved" value="8" accent="accent" />
            <MetricCard label="Evidence" value="Sufficient" accent="green" />
            <MetricCard label="Status" value="Complete" accent="green" />
          </div>
        </div>

        <div className="animate-fade-in-up rounded-2xl border border-accent/20 bg-accent/4 p-6 shadow-sm" style={{ animationDelay: "0.12s" }}>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-foreground">Final Answer</h3>
