}

function EvidencePanel({ visible }: { visible: boolean }) {
  if (!visible) return null;
  return (
    <aside className="w-68 shrink-0 border-l border-border bg-card flex flex-col h-full overflow-hidden">
      <div className="px-5 py-4 border-b border-border shrink-0">
        <h2 className="text-sm font-semibold text-foreground">Evidence</h2>
        <p className="text-xs text-muted-foreground mt-0.5">Sources used by the agent</p>
      </div>
      <div className="flex-1 overflow-y-auto px-3 py-3 space-y-2">
        {SOURCES.map((source, i) => (
          <div key={source.id} className="p-3 rounded-xl border border-border bg-secondary hover:border-accent/25 hover:shadow-sm transition-all duration-150 animate-step-enter" style={{ animationDelay: `${i * 0.06}s` }}>
            <div className="flex items-center gap-1.5 mb-1.5">
              <span className="text-[9px] font-mono font-semibold text-accent">[{source.id}]</span>
              <span className="text-xs font-semibold text-foreground leading-tight">{source.title}</span>
