            <div className="flex items-center gap-1.5 mb-2 flex-wrap">
              <SourceBadge type={source.type} />
              {source.page !== "—" && <span className="text-[9px] text-muted-foreground font-mono">p. {source.page}</span>}
            </div>
            <p className="text-[11px] text-muted-foreground leading-relaxed mb-2 line-clamp-2">"{source.excerpt}"</p>
            <div className="flex items-center justify-between">
              <span className={`text-[10px] font-medium ${source.relevance === "High" ? "text-green-600" : source.relevance === "Medium" ? "text-amber-600" : "text-muted-foreground"}`}>
                ● {source.relevance}
              </span>
              <button className="text-[10px] text-accent hover:text-accent/70 font-medium transition-colors">View</button>
            </div>
          </div>
        ))}
      </div>
    </aside>
  );
}

// ── Inline search bar ─────────────────────────────────────────────────────────
function SearchBar({ onSubmit }: { onSubmit: (q: string) => void }) {
  const [query, setQuery] = useState("");

  return (
    <div className="px-8 py-3 border-b border-border bg-card shrink-0">
      <div className="max-w-2xl mx-auto rounded-xl border border-border bg-secondary flex items-center gap-2 px-4 py-2 focus-within:border-accent/40 transition-all">
