    </div>
  );
}

// ── Complete state ────────────────────────────────────────────────────────────
function CompleteState({ question }: { question: string }) {
  return (
    <div className="flex-1 overflow-y-auto">
      <div className="max-w-2xl mx-auto px-8 py-8 space-y-5">
        <div className="animate-fade-in-up">
          <div className="text-[10px] font-semibold uppercase tracking-widest text-accent mb-1">Agent Research</div>
          <h2 className="text-xl font-semibold text-foreground mb-5" style={{ letterSpacing: "-0.02em" }}>Research complete</h2>

          <div className="p-4 rounded-2xl border border-border bg-card shadow-sm mb-4">
            <div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-1.5">Question</div>
            <p className="text-sm text-foreground leading-relaxed">{question}</p>
          </div>

          <div className="flex gap-2 mb-5">
            <MetricCard label="Iterations" value="3" accent="accent" />
            <MetricCard label="Sources Retrieved" value="8" accent="accent" />
            <MetricCard label="Evidence" value="Sufficient" accent="green" />
            <MetricCard label="Status" value="Complete" accent="green" />
          </div>
        </div>

        <div className="animate-fade-in-up rounded-2xl border border-accent/20 bg-accent/4 p-6 shadow-sm" style={{ animationDelay: "0.12s" }}>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-foreground">Final Answer</h3>
            <span className="flex items-center gap-1 text-[9px] font-semibold uppercase tracking-widest text-green-700 bg-green-50 border border-green-200 px-2.5 py-1 rounded-md">
              <svg viewBox="0 0 10 10" fill="none" className="w-2.5 h-2.5"><path d="M1.5 5l2.5 2.5L8.5 2.5" stroke="#16a34a" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
              Evidence-backed
            </span>
          </div>

          <p className="text-sm text-foreground leading-relaxed mb-2">
            The fall of Valen was primarily caused by <span className="font-medium">Commander Rael's</span> systematic campaign, which dismantled Valen's northern alliance through strategic betrayals and prolonged siege warfare <CitationBadge n={1} /><CitationBadge n={2} />. Council records confirm deliberate provocation and resource hoarding <CitationBadge n={5} />.
          </p>
          <p className="text-sm text-foreground leading-relaxed mb-5">
            Following the city's destruction, seven surrounding regions entered a period of political instability lasting over two decades <CitationBadge n={3} />. Lord Maevan's letters document the immediate strategic vulnerability — the eastern passes were left undefended, a weakness felt for a generation <CitationBadge n={4} /><CitationBadge n={6} />.
          </p>

          <div className="flex items-center gap-4 pt-4 border-t border-accent/15">
            <div className="flex items-center gap-1.5">
              <span className="text-[9px] text-muted-foreground uppercase tracking-wider font-medium">Evidence</span>
              <span className="text-xs font-semibold text-foreground">8 sources</span>
            </div>
            <div className="w-px h-4 bg-border" />
            <div className="flex items-center gap-1.5">
              <span className="text-[9px] text-muted-foreground uppercase tracking-wider font-medium">Iterations</span>
              <span className="text-xs font-semibold text-foreground">3</span>
            </div>
            <div className="w-px h-4 bg-border" />
            <div className="flex items-center gap-1.5">
              <span className="text-[9px] text-muted-foreground uppercase tracking-wider font-medium">Confidence</span>
              <span className="text-xs font-semibold text-green-600">High</span>
            </div>
            <button className="ml-auto text-xs text-accent hover:text-accent/80 font-medium transition-colors">View supporting evidence →</button>
          </div>
        </div>

        <div className="animate-fade-in-up" style={{ animationDelay: "0.2s" }}>
          <h3 className="text-sm font-semibold text-foreground mb-4">Retrieval Timeline</h3>
          <Timeline steps={COMPLETE_STEPS} />
        </div>
      </div>
    </div>
  );
}

// ── Error state ───────────────────────────────────────────────────────────────
function ErrorState({ onRetry, onModify }: { onRetry: () => void; onModify: () => void }) {
  return (
    <div className="flex-1 flex flex-col items-center justify-center px-8 pb-12">
      <div className="max-w-sm w-full text-center animate-fade-in-up">
        <div className="w-14 h-14 rounded-2xl bg-red-50 border border-red-100 flex items-center justify-center mx-auto mb-5">
          <svg viewBox="0 0 24 24" fill="none" className="w-6 h-6"><path d="M12 4v9M12 17v1" stroke="#dc2626" strokeWidth="2" strokeLinecap="round" /><circle cx="12" cy="12" r="9" stroke="#dc2626" strokeWidth="1.5" /></svg>
        </div>
        <h2 className="text-xl font-semibold text-foreground mb-2" style={{ letterSpacing: "-0.02em" }}>Research paused</h2>
        <p className="text-sm text-muted-foreground mb-8 leading-relaxed">Not enough reliable evidence was found to answer this question with sufficient confidence.</p>
        <div className="flex gap-3 justify-center">
          <button onClick={onModify} className="px-4 py-2 rounded-xl border border-border bg-card hover:bg-muted text-sm font-medium text-foreground transition-all shadow-sm">Modify Question</button>
          <button onClick={onRetry} className="px-4 py-2 rounded-xl text-white text-sm font-medium transition-all shadow-sm" style={{ background: "linear-gradient(135deg, #5b5bd6, #818cf8)" }}>Try Another Search</button>
        </div>
      </div>
    </div>
  );
}

// ── Source cards ──────────────────────────────────────────────────────────────
function SourceBadge({ type }: { type: string }) {
  const styles: Record<string, string> = {
    Novel: "bg-violet-50 text-violet-700 border-violet-200",
    "Wiki Article": "bg-blue-50 text-blue-700 border-blue-200",
    Codex: "bg-amber-50 text-amber-700 border-amber-200",
    Letter: "bg-rose-50 text-rose-700 border-rose-200",
    Transcript: "bg-teal-50 text-teal-700 border-teal-200",
    "Official Record": "bg-indigo-50 text-indigo-700 border-indigo-200",
  };
  return <span className={`text-[9px] font-semibold uppercase tracking-widest px-1.5 py-0.5 rounded border ${styles[type] ?? "bg-muted text-muted-foreground border-border"}`}>{type}</span>;
}

function EvidencePanel({ visible }: { visible: boolean }) {
  if (!visible) return null;
  return (
    <aside className="w-68 shrink-0 border-l border-border bg-card flex flex-col h-full overflow-hidden">
      <div className="px-5 py-4 border-b border-border shrink-0">
        <h2 className="text-sm font-semibold text-foreground">Evidence</h2>
        <p className="text-xs text-muted-foreground mt-0.5">Sources used by the agent</p>
      </div>
      <div className="flex-1 overflow-y-auto px-3 py-3 space-y-2">
        {SOURCES.map((source, i) => (
          <div key={source.id} className="p-3 rounded-xl border border-border bg-secondary hover:border-accent/25 hover:shadow-sm transition-all duration-150 animate-step-enter" style={{ animationDelay: `${i * 0.06}s` }}>
            <div className="flex items-center gap-1.5 mb-1.5">
              <span className="text-[9px] font-mono font-semibold text-accent">[{source.id}]</span>
              <span className="text-xs font-semibold text-foreground leading-tight">{source.title}</span>
            </div>
            <div className="flex items-center gap-1.5 mb-2 flex-wrap">
              <SourceBadge type={source.type} />
              {source.page !== "—" && <span className="text-[9px] text-muted-foreground font-mono">p. {source.page}</span>}
            </div>
            <p className="text-[11px] text-muted-foreground leading-relaxed mb-2 line-clamp-2">"{source.excerpt}"</p>
            <div className="flex items-center justify-between">
              <span className={`text-[10px] font-medium ${source.relevance === "High" ? "text-green-600" : source.relevance === "Medium" ? "text-amber-600" : "text-muted-foreground"}`}>
                ● {source.relevance}
              </span>
              <button className="text-[10px] text-accent hover:text-accent/70 font-medium transition-colors">View</button>
            </div>
          </div>
        ))}
      </div>
    </aside>
  );
}

// ── Inline search bar ─────────────────────────────────────────────────────────
function SearchBar({ onSubmit }: { onSubmit: (q: string) => void }) {
  const [query, setQuery] = useState("");

  return (
    <div className="px-8 py-3 border-b border-border bg-card shrink-0">
      <div className="max-w-2xl mx-auto rounded-xl border border-border bg-secondary flex items-center gap-2 px-4 py-2 focus-within:border-accent/40 transition-all">
        <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5 text-muted-foreground shrink-0">
          <circle cx="7" cy="7" r="4" stroke="currentColor" strokeWidth="1.5" />
          <path d="M10 10l2.5 2.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
        <input value={query} onChange={(e) => setQuery(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && query.trim()) { onSubmit(query.trim()); setQuery(""); } }} placeholder="Ask another question about the archive..." className="flex-1 bg-transparent text-sm text-foreground placeholder-muted-foreground outline-none" />
        <button onClick={() => { if (query.trim()) { onSubmit(query.trim()); setQuery(""); } }} disabled={!query.trim()} className="px-3 py-1.5 rounded-lg text-white text-xs font-medium disabled:opacity-30 transition-all" style={{ background: "linear-gradient(135deg, #5b5bd6, #818cf8)" }}>
          Research
        </button>
      </div>
    </div>
  );
}

// ── Icon components ───────────────────────────────────────────────────────────
function HomeIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><path d="M2 7l6-5 6 5v7H10v-4H6v4H2V7z" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" /></svg>; }
function ExploreIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><circle cx="8" cy="8" r="5.5" stroke="currentColor" strokeWidth="1.5" /><path d="M10 6l-1.5 4L5 11l1.5-4L10 6z" stroke="currentColor" strokeWidth="1" strokeLinejoin="round" /></svg>; }
function LibraryIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><rect x="2" y="2" width="4" height="12" rx="1" stroke="currentColor" strokeWidth="1.5" /><rect x="7" y="4" width="4" height="10" rx="1" stroke="currentColor" strokeWidth="1.5" /><rect x="12" y="6" width="2" height="8" rx="1" stroke="currentColor" strokeWidth="1.5" /></svg>; }
function HistoryIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><circle cx="8" cy="8" r="5.5" stroke="currentColor" strokeWidth="1.5" /><path d="M8 5v3l2 2" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg>; }
function AttachIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><path d="M13 7l-5.5 5.5A3.5 3.5 0 0 1 2.5 7.5l5-5A2 2 0 0 1 10.5 5.4L6 10a.5.5 0 0 1-.7-.7L10 4.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg>; }
function ReasoningIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><path d="M8 2a5 5 0 0 1 3 9v1.5a.5.5 0 0 1-.5.5h-5a.5.5 0 0 1-.5-.5V11A5 5 0 0 1 8 2z" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" /><path d="M6.5 14h3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /></svg>; }
function ImageIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><rect x="2" y="3" width="12" height="10" rx="1.5" stroke="currentColor" strokeWidth="1.5" /><circle cx="5.5" cy="6" r="1" fill="currentColor" /><path d="M2 11l3.5-3.5L8 10l2-2 4 3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>; }
function DeepResearchIcon() { return <svg viewBox="0 0 16 16" fill="none" className="w-3.5 h-3.5"><path d="M3 8h10M8 3v10" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /><circle cx="8" cy="8" r="5.5" stroke="currentColor" strokeWidth="1.5" /></svg>; }

// ── App ───────────────────────────────────────────────────────────────────────
export default function App() {
  const [appState, setAppState] = useState<AppState>("empty");
  const [question, setQuestion] = useState("");

  function handleSubmit(q: string) {
    setQuestion(q);
    setAppState("loading");
  }

  useEffect(() => {
    if (appState !== "loading") return;
    const t = setTimeout(() => setAppState("researching"), 2800);
    return () => clearTimeout(t);
  }, [appState]);

  useEffect(() => {
    if (appState !== "researching") return;
    const t = setTimeout(() => setAppState("complete"), 1000);
    return () => clearTimeout(t);
  }, [appState]);

  function handleNewResearch() {
    setAppState("empty");
    setQuestion("");
  }

  const showEvidencePanel = appState === "complete" || appState === "researching";
  const showSearchBar = appState !== "empty" && appState !== "loading";

  return (
    <div className="flex h-full bg-background text-foreground overflow-hidden">
      <Sidebar appState={appState} onNewResearch={handleNewResearch} />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <Topbar onNewResearch={handleNewResearch} />

        {showSearchBar && <SearchBar onSubmit={handleSubmit} />}

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 flex flex-col overflow-hidden">
            {appState === "empty" && <EmptyState onSubmit={handleSubmit} />}
            {appState === "loading" && <LoadingState question={question} />}
            {appState === "researching" && <ResearchingState question={question} />}
            {appState === "complete" && <CompleteState question={question} />}
            {appState === "error" && <ErrorState onRetry={() => handleSubmit(question)} onModify={handleNewResearch} />}
          </div>
          <EvidencePanel visible={showEvidencePanel} />
        </div>
      </div>
    </div>
  );
}

