@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500&display=swap');
@import 'tailwindcss';

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-ring: var(--ring);
  --radius-DEFAULT: var(--radius);
}

:root {
  --background: #f2f2f7;
  --foreground: #111118;
  --card: #ffffff;
  --card-foreground: #111118;
  --primary: #5b5bd6;
  --primary-foreground: #ffffff;
  --secondary: #f8f8fc;
  --secondary-foreground: #4a4a6a;
  --muted: #ededf5;
  --muted-foreground: #8888aa;
  --accent: #5b5bd6;
  --accent-foreground: #ffffff;
  --border: #e4e4ee;
  --ring: #5b5bd6;
  --radius: 0.875rem;

  --green: #16a34a;
  --amber: #d97706;
  --red: #dc2626;
}

html, body, #root {
  height: 100%;
  font-family: 'Inter', sans-serif;
}

* {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

*:hover {
  scrollbar-color: #25252f transparent;
}

*::-webkit-scrollbar {
  width: 4px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  background-color: transparent;
  border-radius: 4px;
}

*:hover::-webkit-scrollbar-thumb {
  background-color: #25252f;
}

@keyframes pulse-ring {
  0% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0.4); }
  70% { box-shadow: 0 0 0 8px rgba(99, 102, 241, 0); }
  100% { box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); }
}

@keyframes spin-slow {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@keyframes fade-in-up {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes step-enter {
  from { opacity: 0; transform: translateX(-6px); }
  to { opacity: 1; transform: translateX(0); }
}

.animate-pulse-ring { animation: pulse-ring 2s ease-out infinite; }
.animate-spin-slow { animation: spin-slow 2s linear infinite; }
.animate-fade-in-up { animation: fade-in-up 0.4s ease-out both; }
.animate-step-enter { animation: step-enter 0.35s ease-out both; }

