  const [appState, setAppState] = useState<AppState>("empty");
  const [question, setQuestion] = useState("");

  function handleSubmit(q: string) {
    setQuestion(q);
    setAppState("loading");
  }

  useEffect(() => {
    if (appState !== "loading") return;
    const t = setTimeout(() => setAppState("researching"), 2800);
    return () => clearTimeout(t);
  }, [appState]);

  useEffect(() => {
    if (appState !== "researching") return;
    const t = setTimeout(() => setAppState("complete"), 1000);
    return () => clearTimeout(t);
  }, [appState]);

  function handleNewResearch() {
    setAppState("empty");
    setQuestion("");
  }

  const showEvidencePanel = appState === "complete" || appState === "researching";
  const showSearchBar = appState !== "empty" && appState !== "loading";

  return (
    <div className="flex h-full bg-background text-foreground overflow-hidden">
      <Sidebar appState={appState} onNewResearch={handleNewResearch} />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <Topbar onNewResearch={handleNewResearch} />

        {showSearchBar && <SearchBar onSubmit={handleSubmit} />}

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 flex flex-col overflow-hidden">
            {appState === "empty" && <EmptyState onSubmit={handleSubmit} />}
            {appState === "loading" && <LoadingState question={question} />}
            {appState === "researching" && <ResearchingState question={question} />}
            {appState === "complete" && <CompleteState question={question} />}
            {appState === "error" && <ErrorState onRetry={() => handleSubmit(question)} onModify={handleNewResearch} />}
          </div>
          <EvidencePanel visible={showEvidencePanel} />
        </div>
      </div>
    </div>
  );
}

