def render_question_input() -> None:
    st.markdown(
        """
        <div class="hero">
          <div class="eyebrow">Agentic Research</div>
          <h1>What would you like to investigate?</h1>
          <p>Ask a complex question. AlchemAI searches, evaluates evidence, and continues retrieving information until it can provide a reliable answer.</p>
