def run_document_qa_agent(question: str) -> Iterable[AgentUpdate]:
    """Replace this demo generator with your direct Python backend call.

    Expected behavior:
    - yield AgentUpdate objects as each search/evaluation iteration finishes
    - include any newly discovered sources
    - set answer when the final cited answer is ready

    If your backend is not a generator yet, call it once and return a single
    AgentUpdate with all steps, sources, and answer.
    """
    visible_steps: list[ReasoningStep] = []
    visible_sources: list[Source] = []

    for index, step in enumerate(DEMO_STEPS, start=1):
        visible_steps.append(step)
        source_count = min(len(DEMO_SOURCES), 2 + index)
        visible_sources = DEMO_SOURCES[:source_count]
        yield AgentUpdate(
            steps=visible_steps.copy(),
            sources=visible_sources.copy(),
            confidence="Pending",
            status="Researching",
        )
        time.sleep(0.45)

    answer = (
        "The fall of Valen was primarily caused by Commander Rael's systematic "
        "campaign, which dismantled Valen's northern alliance through strategic "
        "betrayals and prolonged siege warfare [1][2]. Council records also cite "
        "deliberate provocation and resource hoarding by Rael's faction [5].\n\n"
        "After the city's destruction, seven surrounding regions entered political "
        "instability for more than two decades [3]. Lord Maevan's correspondence "
        "shows the immediate strategic consequence: the eastern passes were left "
        "undefended, creating a vulnerability felt for a generation [4][6]."
    )
    yield AgentUpdate(
        steps=visible_steps,
        sources=visible_sources,
        answer=answer,
        confidence="High",
        status="Complete",
    )


