            st.markdown(f"**What was found:** {step.found}")
            if step.sufficient:
                st.markdown('<span class="badge badge-green">Evidence sufficient</span>', unsafe_allow_html=True)
            else:
                st.markdown('<span class="badge badge-amber">More evidence needed</span>', unsafe_allow_html=True)
            if step.meta:
                st.caption(step.meta)


def render_sources(sources: list[Source]) -> None:
    st.subheader("Evidence")
    st.caption("Sources used by the agent")
    if not sources:
        st.info("Sources will appear here as retrieval completes.")
        return

    for source in sources:
        relevance_class = "badge-green" if source.relevance == "High" else "badge-amber"
        page = f"Page {source.page}" if source.page != "-" else "No page"
        st.markdown(
            f"""
            <div class="source-card">
              <div style="display:flex;gap:.35rem;align-items:center;margin-bottom:.35rem;">
                <strong>[{source.id}] {html.escape(source.title)}</strong>
              </div>
              <div class="source-meta">{html.escape(source.doc_type)} · {html.escape(page)} · {html.escape(source.evidence_type)}</div>
              <p style="font-size:.85rem;margin:.6rem 0;color:#4a4a6a;">"{html.escape(source.excerpt)}"</p>
              <span class="badge {relevance_class}">{source.relevance} relevance</span>
            </div>
            """,
            unsafe_allow_html=True,
        )


def render_final_answer(update: AgentUpdate) -> None:
    if not update.answer:
        return

    answer_html = html.escape(update.answer)
    for citation_id in range(1, 10):
        answer_html = answer_html.replace(
            f"[{citation_id}]",
            f'<span class="citation">{citation_id}</span>',
        )
    answer_html = answer_html.replace("\n\n", "</p><p>")

    st.markdown(
        f"""
        <div class="answer-panel">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:.7rem;">
            <h3 style="margin:0;">Final Answer</h3>
            <span class="badge badge-green">Evidence-backed</span>
          </div>
          <p>{answer_html}</p>
          <hr style="border:none;border-top:1px solid rgba(91,91,214,.15);margin:1rem 0;">
          <div style="display:flex;gap:1.25rem;flex-wrap:wrap;font-size:.85rem;">
            <span><strong>{len(update.sources)}</strong> sources</span>
            <span><strong>{len(update.steps)}</strong> reasoning steps</span>
            <span><strong>{html.escape(update.confidence)}</strong> confidence</span>
          </div>
        </div>
        """,
        unsafe_allow_html=True,
    )


def render_research_workspace(update: AgentUpdate) -> None:
    st.markdown('<div class="eyebrow">Agent Research</div>', unsafe_allow_html=True)
    st.title("Research complete" if update.answer else "Research in progress")
    st.markdown(
        f"""
        <div class="panel">
          <div class="metric-label">Question</div>
          <div>{html.escape(st.session_state.question)}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
    st.write("")
    render_metrics(update)
    st.write("")
    render_final_answer(update)
    st.write("")
    render_reasoning_trail(update.steps)


def run_live_research() -> None:
    workspace = st.empty()
    evidence = st.empty()

    for update in run_document_qa_agent(st.session_state.question):
        st.session_state.current_update = update
        with workspace.container():
            render_research_workspace(update)
        with evidence.container():
            render_sources(update.sources)


def main() -> None:
    configure_page()
    initialize_state()
    render_sidebar()

    if not st.session_state.has_run:
        render_question_input()
        return

    main_column, evidence_column = st.columns([2.25, 1], gap="large")
    if st.session_state.current_update.answer:
        with main_column:
            render_research_workspace(st.session_state.current_update)
        with evidence_column:
            render_sources(st.session_state.current_update.sources)
    else:
        with main_column:
            run_live_research()


if __name__ == "__main__":
    main()
